import java.util.Objects;

public final class Order {

    private final OrderId id;
    private final CustomerId customerId;
    private OrderStatus status;

    private Order(OrderId id, CustomerId customerId, OrderStatus status) {
        this.id = id;
        this.customerId = customerId;
        this.status = status;
    }

    public static Order place(OrderId id, CustomerId customerId) {
        return new Order(Objects.requireNonNull(id), Objects.requireNonNull(customerId), OrderStatus.PENDING);
    }

    public OrderId id() {
        return id;
    }

    public CustomerId customerId() {
        return customerId;
    }

    public synchronized OrderStatus status() {
        return status;
    }

    public boolean belongsTo(CustomerId caller) {
        return customerId.equals(caller);
    }

    public synchronized void cancel(CustomerId caller) {
        if (!belongsTo(caller)) throw new OrderNotFoundException(id);
        if (status != OrderStatus.PENDING) throw new OrderNotCancellableException(id, status);
        status = OrderStatus.CANCELLED;
    }
}
